import logging
import sys
import traceback

import six
from paramiko import SSHException
from ute_common_abstract_core import instance_loader
from ute_common_abstract_core.exceptions import InvalidConfigurationContent
from ute_ue.config import loggers as ta_ue_logging
from ute_ue.exceptions import CreateAndroidUeSShException, UnknownUe
from ute_ue.lteuepool import CfgFileBasedUePool

from ta_ue_plugin_android.pyro_client import PyroClient
from ta_ue_plugin_android.ue.common.specific_keywords_list import get_android_specific_keywords_list
from ta_ue_plugin_android.uepc.take_care_thread import IAbstractTakeCarer, TakeCareThread
from ta_ue_plugin_android.uepc.ue_pool_on_server import UE_RESERVATION_TIME
from ta_ue_plugin_android.uepc.uepool_backends import QualcommUePool2Backed
from ta_ue_plugin_android.uepc.uepool_backends import SoundcardAndroidUePool2Backed
from ta_ue_plugin_android.uepc.ues_reservation_list import UesReservationList

ANDROID_KEEP_RESERVATION_THREAD_UPDATE_DURATION = 1
ANDROID_UE_POOL_THREAD_CLOSE_TIMEOUT = 3 * ANDROID_KEEP_RESERVATION_THREAD_UPDATE_DURATION


class AndroidUePool(CfgFileBasedUePool, IAbstractTakeCarer):
    """UePool for Android UEs"""
    _android_specific_keywords = get_android_specific_keywords_list()

    def __init__(self, config_file_path=None, inline_config=None, keep_reservation_duration=None):
        """

        :param config_file_path:
        :param inline_config:
        :param keep_reservation_duration:
        """
        if inline_config is None:
            inline_config = []
        super(AndroidUePool, self).__init__(config_file_path, inline_config)
        self.connections = {}
        raw_logger = logging.getLogger("ute_ue")
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UEPOOL'})
        keep_reservation_duration = keep_reservation_duration or ANDROID_KEEP_RESERVATION_THREAD_UPDATE_DURATION
        self._keep_reservation_thread = TakeCareThread(self, keep_reservation_duration, thread_namesufix='-in-AndroidUePool')
        self._ues_reservation_list = UesReservationList(UE_RESERVATION_TIME)

    def _prepare_notification(self, pyro_obj, config, ue_serial_number, ue_name, ue_class_name, ue_model):
        ue_pc_ip = config['ue_pc_ip']
        login = config['login']
        password = config['password']
        msg = """
        -------- NEW UE RESERVED ----------
        UE Class: {}
        UE PC IP: {}
        UE PC details: {} / {}
        UE Name: {}
        UE SN: {}
        UE Model: {}
        -------------------------------------
        """.format(ue_class_name, ue_pc_ip, login, password, ue_name, ue_serial_number, ue_model)
        if 'mock' not in str(ue_model):
            pyro_obj.notifier.update_message(msg)

    def take_care(self, key, ue):  # pylint: disable=arguments-differ
        """
        Callback method for TakeCareThread class to keeping reservation
        :param key:
        :param ue:
        :return:
        """
        self.logger.debug("before end keep reservation for Ue {}".format(key))
        ue.android_keep_reservation()
        self._ues_reservation_list.update_ue_reservation_time(ue.serial_number)
        self.logger.debug("Send keep reservation for Ue {}".format(key))

    def report_exception(self, key, value, exception):
        """
        Callback method for TakeCareThread class to keeping reservation
        :param key:
        :param value:
        :param exception:
        :return:
        """
        trace = traceback.format_exc()
        msg = "Exception inside _run_thread_android_keep_reservation {} \ntrace\n{}".format(exception, trace)
        self.logger.warning(msg)

    def _withdraw_device_from_available_devices(self, ue_name, ue):  # pylint: disable=arguments-differ
        self.logger.debug("start _withdraw_ue_from_available_ues, new version 20.07.2017")
        self._ues_reservation_list.update_ue_reservation_time(ue.serial_number)
        ue.start_reservation_veryfying()
        self._ues_reservation_list.update_ue_reservation_time(ue.serial_number)
        self._keep_reservation_thread.add_careable(ue_name, ue)
        super(AndroidUePool, self)._withdraw_device_from_available_devices(ue_name, ue)
        self.logger.debug("end _withdraw_ue_from_available_ues")

    def release_ue(self, ue):
        """
        Allow UE to be reused - it should be in pool of available UEs. (public API)
        :raises: :py:class:`ute_ue.exceptions.UnknownUe`: If given ue has not been returned from this pool via get_ue()
        :return: None
        """
        serial_number = ue.serial_number
        try:
            self._keep_reservation_thread.remove_careable(serial_number)
        except (KeyError, AttributeError):
            raise UnknownUe('UE: {} is not reserved from AndroidUePool'.format(serial_number))
        self.logger.info('AndroidUePool UE released with serial number: {}'.format(serial_number))

    def create_device(self, ue_name, ue_config):  # pylint: disable=arguments-differ
        """
        Create instance of device

        :param ue_name: name of UE
        :param ue_config: configuration of UE
        :return: device instance
        """
        try:
            pdn_config = self._get_pdn_config()
            if pdn_config:
                ue_config['CONSTRUCTOR_PARAMETERS']['configuration']['PDN'] = pdn_config
            config = ue_config['CONSTRUCTOR_PARAMETERS']['configuration']
            ip = config['ue_pc_ip']
            self._ensure_connected_to_ip(ip, config)
            ue_class_name = ue_config['CLASS']
            serial_number = self._get_serial_number_for_ue(ue_class_name, ue_config, config)
            ue_class = self.get_device_class(class_name=ue_class_name)  # will call convert_device_type_2_device_class_fullname()
            constructor_params = {'name': ue_name,
                                  'serial_number': serial_number,
                                  'configuration': config,
                                  'pyro_client': self.connections[ip],
                                  'reservation_validator': lambda: self._ues_reservation_list.is_still_reserved(serial_number)}
            self._ues_reservation_list.update_ue_reservation_time(serial_number)
            created_ue = instance_loader.create_class_instance(class_object=ue_class, constructor_params=constructor_params)
            created_ue.prepare_ue()
            self._prepare_notification(self.connections[ip], config, serial_number, ue_name, ue_class, created_ue.ue_model)
            return created_ue
        except KeyError as e:
            trace = traceback.format_exc()
            msg_pattern = "Configuration is not valid for Android UE: %s. Expected keyword: %s\nMore trace: %s"
            raise InvalidConfigurationContent(msg_pattern % (ue_name, e.args[0], str(trace)))

    _create_device = create_device  # for backward compatibility (deprecated but exists till all switch to new API)

    def _get_pdn_config(self):
        android_ue_pdn_config = {}
        from ute_common_abstract_core.config import Config as CoreConfig
        pdn_config = None
        whole_config = CoreConfig().get_config()
        if whole_config and ('PDN' in whole_config):
            pdn_config = whole_config['PDN']
        if pdn_config:
            ue_pool_name = self.__class__.__name__
            for pdn_name, pdn_config_per_ue_pool in pdn_config.items():
                if ue_pool_name in pdn_config_per_ue_pool:
                    android_ue_pdn_config[pdn_name] = pdn_config_per_ue_pool[ue_pool_name]
        return android_ue_pdn_config

    @classmethod
    def convert_device_type_2_device_class_fullname(cls, device_type):
        """
        Encapsulate convention how to produce full package.module.class name for given Device type

        (Default convention from ute_common_abstract_core/device_pool.py doesn't work for ta_ue_plugin_android package structure)

        :param device_type: Device type (must be CamelCase name)
        :return: full package.module.class name
        """
        ue_type2class_fullname = {'AndroidUe': 'ta_ue_plugin_android.ue.android.android_ue.AndroidUe',
                                  'SoundcardAndroidUe': 'ta_ue_plugin_android.ue.android.soundcard.soundcardandroid_ue.SoundcardAndroidUe',
                                  'QualcommNoLicenseUe': 'ta_ue_plugin_android.ue.at_cmds_ue.at_cmds_ue.AtCmdsUe',
                                  'AtCmdsUe': 'ta_ue_plugin_android.ue.at_cmds_ue.at_cmds_ue.AtCmdsUe'}
        class_fullname = ue_type2class_fullname[device_type]
        return class_fullname

    def _get_serial_number_for_ue(self, ue_class_name, ue_config, config):
        if (ue_class_name == 'AndroidUe') or (ue_class_name == 'SoundcardAndroidUe'):
            serial_number = self._get_serial_number_for_android(ue_config)
            if ue_class_name == 'SoundcardAndroidUe':
                serial_number = SoundcardAndroidUePool2Backed.create_soundcard_serial_number(serial_number)
            return serial_number
        elif ue_class_name in ['QualcommNoLicenseUe', 'AtCmdsUe']:
            return self._get_serial_number_for_qualcomm(config)
        else:
            known = 'AndroidUe, SoundcardAndroidUe, QualcommNoLicenseUe, AtCmdsUe'
            raise InvalidConfigurationContent("Unknown UE class: {}, known classes in this pool: {}".format(ue_class_name, known))

    def _get_serial_number_for_qualcomm(self, config):
        return QualcommUePool2Backed.create_serial_number_from_configuration__or_none(config)

    def _get_serial_number_for_android(self, ue_config):
        return ue_config['CONSTRUCTOR_PARAMETERS']['serial_number']

    def shutdown(self):
        """
        Shutdown

        avoid: RuntimeError: dictionary changed size during iteration
        """
        for ue_name in list(self._taken_devices):
            self._return_device_to_available_devices(ue_name)
            self._keep_reservation_thread.remove_careable(ue_name)
        self._keep_reservation_thread.clear_and_finish()
        if self._keep_reservation_thread.is_alive():
            self.logger.debug("Waiting for take care Thread to finish.")
            self._keep_reservation_thread.join()

        for ip, pyro_client in self.connections.items():
            if pyro_client:
                self.logger.debug("Shutting down pool on server on UE PC: {}".format(ip))
                pyro_client.run_on_pool_controller('shutdown_pool')
                pyro_client.shutdown()
        self.connections.clear()

    def _ensure_connected_to_ip(self, ip, config):
        if self._is_need_to_connnect_to_ue_pc(ip):
            try:
                self.connections[ip] = self._create_connected_pyro_client(config)
            except SSHException as e:
                self.logger.exception(e, exc_info=True)
                msg = "While connecting to Android UE PC {} occurs ssh error: {}: {}".format(ip, e.__class__.__name__, e)
                w602_workaround = CreateAndroidUeSShException(msg)
                six.reraise(w602_workaround.__class__, w602_workaround, sys.exc_info()[2])
            except Exception as e:  # pylint: disable=broad-except
                self.logger.exception(e, exc_info=True)
                six.reraise(e.__class__, e, sys.exc_info()[2])

    def _is_need_to_connnect_to_ue_pc(self, ip):
        return ip not in self.connections

    def _create_connected_pyro_client(self, config):
        client = self._new_pyro_client(config)
        client.connect()
        return client

    def _new_pyro_client(self, config):
        pyro_client = self._new_pyro_client_core(config)
        return pyro_client

    def _new_pyro_client_core(self, config):
        return PyroClient(config)
